import React, { useEffect, useState } from "react";
import { motion, AnimatePresence } from "framer-motion";

/**
 * Enhanced LoginModal.jsx
 * - Twilio OTP login, styled to match NextGen Health theme
 */

export default function LoginModal({ open, onClose, onLogin }) {
  const [step, setStep] = useState(0); // 0: phone input, 1: OTP verify
  const [phone, setPhone] = useState("");
  const [name, setName] = useState("");
  const [otp, setOtp] = useState("");
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");
  const [demoOtp, setDemoOtp] = useState(null);

  useEffect(() => {
    if (!open) {
      setStep(0);
      setPhone("");
      setName("");
      setOtp("");
      setDemoOtp(null);
      setMessage("");
      setLoading(false);
    }
  }, [open]);

  async function requestOtp(e) {
    e?.preventDefault();
    if (!phone) return setMessage("Enter your phone number (e.g. +91...)");
    setLoading(true);
    try {
      const res = await fetch("/api/auth/otp/request", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ phone }),
      });
      const data = await res.json();
      setLoading(false);
      if (data.ok) {
        setStep(1);
        setMessage("OTP sent! Check your phone.");
        if (data.demo && data.otp) setDemoOtp(data.otp);
      } else {
        setMessage(data.error || "Failed to send OTP");
      }
    } catch (err) {
      console.error(err);
      setLoading(false);
      setMessage("Network error. Try again later.");
    }
  }

  async function verifyOtp(e) {
    e?.preventDefault();
    if (!otp) return setMessage("Enter the OTP you received");
    setLoading(true);
    try {
      const res = await fetch("/api/auth/otp/verify", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ phone, otp, name }),
      });
      const data = await res.json();
      setLoading(false);
      if (data.ok) {
        setMessage("Login successful 🎉");
        onLogin(data);
        setTimeout(onClose, 700);
      } else {
        setMessage(data.error || "Invalid OTP, please try again.");
      }
    } catch (err) {
      console.error(err);
      setLoading(false);
      setMessage("Network error verifying OTP.");
    }
  }

  if (!open) return null;

  return (
    <AnimatePresence>
      <motion.div
        key="backdrop"
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        className="modal-backdrop"
        onClick={onClose}
      >
        <motion.div
          key="modal"
          initial={{ scale: 0.95, opacity: 0 }}
          animate={{ scale: 1, opacity: 1 }}
          exit={{ scale: 0.95, opacity: 0 }}
          transition={{ duration: 0.25 }}
          className="modal-card"
          onClick={(e) => e.stopPropagation()}
        >
          <div className="modal-header">
            <h3>🔐 Sign in / Register</h3>
            <button className="close-btn" onClick={onClose}>✕</button>
          </div>

          <div className="modal-body">
            {step === 0 && (
              <form onSubmit={requestOtp}>
                <input
                  className="modal-input"
                  placeholder="+91 98xxxxxxxx"
                  value={phone}
                  onChange={(e) => setPhone(e.target.value)}
                />
                <input
                  className="modal-input"
                  placeholder="Your name (optional)"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                />

                <div className="row">
                  <button className="btn full" type="submit" disabled={loading}>
                    {loading ? "Sending..." : "Send OTP"}
                  </button>
                  <button
                    type="button"
                    className="btn btn-outline full"
                    onClick={() => alert("Google Sign-in can be added later")}
                  >
                    Google
                  </button>
                </div>

                {demoOtp && (
                  <div className="demo-otp">
                    Demo OTP: <strong>{demoOtp}</strong>
                  </div>
                )}
              </form>
            )}

            {step === 1 && (
              <form onSubmit={verifyOtp}>
                <input
                  id="otpInput"
                  className="modal-input"
                  placeholder="Enter OTP"
                  value={otp}
                  onChange={(e) => setOtp(e.target.value)}
                />
                <div className="row">
                  <button className="btn full" type="submit" disabled={loading}>
                    {loading ? "Verifying..." : "Verify"}
                  </button>
                  <button
                    type="button"
                    className="btn btn-outline full"
                    onClick={() => setStep(0)}
                  >
                    Back
                  </button>
                </div>
              </form>
            )}

            {message && <div className="msg">{message}</div>}
          </div>
        </motion.div>
      </motion.div>
    </AnimatePresence>
  );
}
